def skill():
    N = [1, 2, 5, 12]
    den = sum(binomial(3, m) * N[m] * 3**(3 - m) for m in range(4))
    num = 3 * sum(binomial(2, m) * N[m] * 3**(2 - m) for m in range(3))
    v = Fraction(num, den)
    return v.numerator + v.denominator

def standard():
    from itertools import product
    def sw(c, k):
        c = list(c)
        if k <= 3:
            c[k-1], c[k] = c[k], c[k-1]
        return tuple(c)
    st = tuple("AABB")
    tot = fav = 0
    for seq in product(range(1, 7), repeat=3):
        c = st
        for k in seq:
            c = sw(c, k)
        if c == st:
            tot += 1
            fav += seq[1] >= 4
    v = Fraction(fav, tot)
    return v.numerator + v.denominator

def unique():
    return [standard()]
